type Entities=Map<bigint,SqliteRow>;
function choice<T extends string>(v:unknown,values:readonly T[]):T{if(typeof v!=="string"||!values.includes(v as T))throw Error("owned enum differs");return v as T}
async function checkpoint(options:ArtifactSqliteOptions,position:number,total:number):Promise<void>{if(position%256===0)await artifactSqliteCheckpoint(options,"reconstructSnapshot",position,total,position>0)}
async function entities(rows:readonly SqliteRow[],columns:number,floats:readonly Ieee754Column[],options:ArtifactSqliteOptions):Promise<Entities>{const result:Entities=new Map();for(let position=0;position<rows.length;position++){await checkpoint(options,position,rows.length);const row=rows[position]!;if(row.values.length!==columns+floats.length*2||row.rowid<=0n||artifactSqliteInteger(row,0)!==row.rowid||result.has(row.rowid))throw Error("EN1991 requires exact fields and unique positive aliased identities");for(const column of floats)readBinary64(row,column.index,floats);result.set(row.rowid,row)}return result}
async function ordered(rows:Iterable<SqliteRow>,parent:bigint,options:ArtifactSqliteOptions):Promise<SqliteRow[]>{const result:SqliteRow[]=[];for(const row of rows){await checkpoint(options,result.length,0);if(artifactSqliteInteger(row,1)!==parent)throw Error("EN1991 entity has a foreign parent");result.push(row)}return artifactSqliteOrderedRowsControlled(result,2,options)}
async function childGroups(rows:Entities,parents:Entities,options:ArtifactSqliteOptions):Promise<Map<bigint,SqliteRow[]>>{const result=new Map<bigint,SqliteRow[]>();let position=0;for(const row of rows.values()){await checkpoint(options,position++,rows.size);const parent=artifactSqliteInteger(row,1);if(!parents.has(parent))throw Error("EN1991 accidental child has an unknown owning case");const children=result.get(parent)??[];children.push(row);result.set(parent,children)}return result}
function u8(value:number):bigint{if(!Number.isInteger(value)||value<0||value>255)throw Error("EN1991 field exceeds unsigned8");return BigInt(value)}
function readU8(row:SqliteRow,column:number):number{const value=artifactSqliteInteger(row,column);if(value<0n||value>255n)throw Error("EN1991 field exceeds unsigned8");return Number(value)}
function flag(value:boolean):bigint{if(typeof value!=="boolean")throw Error("EN1991 boolean is not owned");return value?1n:0n}
function annex(value:unknown):En1991SqliteSnapshot["annex"]{if(value!=="En"&&value!=="De")throw Error("EN1991 annex choice is not owned");return value}
function fireLoadBasis(value:unknown):En1991SqliteSnapshot["fireLoadBasis"]{if(value!=="occupancyTable"&&value!=="userSpecified")throw Error("EN1991 fire load basis is not owned");return value}
function fireMode(value:unknown):En1991SqliteSnapshot["fireMode"]{if(value!=="none"&&value!=="nominal"&&value!=="parametric")throw Error("EN1991 fire mode is not owned");return value}
function fireCurve(value:unknown):En1991SqliteSnapshot["fireCurve"]{if(value!=="standard"&&value!=="external"&&value!=="hydrocarbon"&&value!=="parametric")throw Error("EN1991 fire curve is not owned");return value}
function structureKind(value:unknown):En1991SqliteSnapshot["structureKind"]{if(value!=="building"&&value!=="bridge")throw Error("EN1991 structure kind is not owned");return value}
async function write(out:ArtifactSqliteProjection,table:string,id:bigint,cells:readonly Ieee754Cell[],floats:readonly Ieee754Column[],options:ArtifactSqliteOptions):Promise<void>{await out.insert(table,encodeIeee754Cells([id,...cells],floats,options.maxColumns).slice(1),id)}

