 for(let position=0;position<s.selfWeightElements.length;position++){const f=s.selfWeightElements[position]!;await write(out,"en1991_self_weight",BigInt(position+1),[1n,BigInt(position),f.id,f.material,f.thickness,f.assumedGk],SELF_WEIGHT_FLOATS,options)}
